import os
import time
import warnings

from taf.hw.pdu import pdu
from typing import List, Union, Optional
from taf.fdsw.rc import RescueConsoleConnection
from taf.ul.alarms_watchdog import Alarm
from pathlib import Path
from robot.libraries.BuiltIn import BuiltIn

from taf.rfrl.csv4all.resources.node.exceptions import FallbackFaultNotAppear
from taf.rfrl.csv4all.resources.node.feature.netact.exceptions import SoftwareStatusError
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, wait_until_success, run_and_continue_on_failure, \
    time_limit, run_process
from taf.rfrl.csv4all.resources.node.feature.utilities.feature_node import FeatureNode

warnings.filterwarnings('ignore')
pdu = pdu()


class FdswNode(FeatureNode):

    def __init__(self, node_mrbts_id: str, source_sw: str, target_sw: str, node_alias: Optional[str] = None,
                 node_vm: Union[str, dict] = None, secondary_vm: Union[str, dict] = None,
                 bts_host_ip: Optional[str] = "192.168.255.129", external_dcap_host: Optional[str] = None,
                 dcap_port: Optional[str] = "9443", dcap_custom_profiles: Optional[dict] = None,
                 hw_to_onair_timeout: Optional[int] = 900, alarm_timer: Optional[int] = 60,
                 custom_allowed_alarms: Optional[list] = None, temporary_allowed_alarms: Optional[list] = None,
                 critical_alarms: List[Union[str, Alarm]] = None, pdu_config: Optional[list] = None,
                 logs_dir: Optional[str] = None, testline_scout_name: Optional[str] = None,
                 use_dcap: Optional[bool] = False, verify_syslog: Optional[bool] = True,
                 syslog_ignored_prints: Union[list, str] = None, user_syslog_suspicious_prints: Union[list, str] = None,
                 webem_username: str = 'Nemuadmin', webem_password: str = 'nemuuser',
                 node_ssh_username: str = "toor4nsn", node_ssh_password: str = "oZPS0POrRieRtu",
                 check_mplane: bool = True, airphone_details: dict = None, check_amf: bool = True,
                 admin_setup_timeout: int = 120, setup_energy_saving: bool = False,
                 ru_manager_yaml_file: Union[str, None] = None, **kwargs):
        super().__init__(node_mrbts_id, node_alias, node_vm, secondary_vm, bts_host_ip, external_dcap_host, dcap_port,
                         dcap_custom_profiles, hw_to_onair_timeout, alarm_timer, source_sw, target_sw,
                         custom_allowed_alarms, temporary_allowed_alarms, critical_alarms, pdu_config, logs_dir,
                         testline_scout_name, use_dcap, verify_syslog, syslog_ignored_prints,
                         user_syslog_suspicious_prints, webem_username, webem_password, node_ssh_username,
                         node_ssh_password, check_mplane, None, airphone_details, check_amf,
                         admin_setup_timeout, setup_energy_saving, ru_manager_yaml_file, **kwargs)
        self.modules_with_netboot_off = ["ASOG", "ASOH", "ASIM"]
        self.fdsw_remote_tunnel = None
        self.fdsw_connection = None
        self.node_vm = node_vm
        self.target_sw = target_sw
        self.yaft_command = None
        self.download_path = None
        self.master_netboot_changed = False
        self.slave_netboot_changed = False

    @method_decorator("node_alias")
    def setup_fdsw_connection(self, username: str = "Nemuadmin", password: str = "nemuuser",
                              local_host="127.0.0.1", local_port: int = 8888, log_level: str = "INFO") -> None:
        if not self.fdsw_remote_tunnel:
            remote_details = {"ssh_host": self.node_vm.get("host"), "ssh_port": 22, "ssh_username": 'ute',
                              "ssh_password": 'ute', "remote_host": '192.168.255.129', "remote_port": 443,
                              "local_host": local_host, "local_port": local_port}
            self.fdsw_remote_tunnel = RescueConsoleConnection.setup_remote(**remote_details)
        if "FDSW19" in self.source_sw:
            self.fdsw_connection = RescueConsoleConnection(local_host, local_port, username, password,
                                                           fdsw_version="fdsw19",
                                                           auto_discover=False, secure=True, log_level=log_level)
        else:
            self.fdsw_connection = RescueConsoleConnection(local_host, local_port, username, password,
                                                           auto_discover=True, secure=True,
                                                           log_level=log_level)

    @method_decorator("node_alias")
    def perform_yaft_to_fdsw(self, yaft_path: str, virtualenv_dir: str = None):
        test_logger(f"Performing yaft to {self.source_sw}")
        wait_until_success(900, 30, self.run_yaft, self.source_sw, yaft_path, virtualenv_dir=virtualenv_dir)

    @method_decorator("node_alias")
    def teardown_fdsw_connection(self):
        if self.fdsw_connection:
            try:
                self.fdsw_connection.disconnect()
                RescueConsoleConnection.disconnect_remote(remote_connection=self.fdsw_remote_tunnel)
            except Exception as e:
                test_logger(e, console=False)

    @method_decorator("node_alias")
    def software_update_rc(self, timeout: int = 3000) -> None:
        slot_id = "2" if self.fdsw_connection.get_active_sw_partition() == "1" else "1"
        test_logger("Software update started")
        with time_limit(timeout):
            self.fdsw_connection.software_update(sw_slot_id=slot_id, sw_pkg_path=self.target_sw_path, timeout=timeout,
                                                 activate=True)
        test_logger("Software update finished")

    @method_decorator("node_alias")
    def update_sw_operation_rc(self) -> None:
        try:
            run_and_continue_on_failure(self.fdsw_connection.disable_ethernet_port_security)
            wait_until_success(3600, 30, self.software_update_rc)
        except Exception as e:
            test_logger(e, console=False)
            wait_until_success(60, 10, self.get_technical_logs, self.logs_dir)
            raise

    @method_decorator("node_alias")
    def setup_fdsw(self, **kwargs):
        test_logger("Setup Rescue Console")
        wait_until_success(600, 60, self.setup_fdsw_connection, **kwargs)

    @method_decorator("node_alias")
    def operations_after_update_from_fdsw(self):
        test_logger("Preparing node after update from fdsw")
        self.reset_admin()
        test_logger("Enabling ssh access")
        wait_until_success(1200, 10, self.admin.enable_ssh_access)
        test_logger("Restoring swconfig")
        self.restore_swconfig()
        self.reset_site()
        wait_until_success(180, 30, self.perform_node_commissioning)
        self.reboot_fhs_if_exists()
        wait_until_success(2400, 30, self.update_software_on_affected_modules)

    @method_decorator("node_alias")
    def restore_swconfig(self):
        self.put_swconfig_to_smod(self.backup_swconfig_path_primary_smod)

    @method_decorator("node_alias")
    def reboot_fhs_if_exists(self) -> None:
        tl_init = BuiltIn().get_variable_value("${tl}")
        for tech in ["enbs", "gnbs"]:
            tl_enb = getattr(tl_init, tech)
            if tl_enb:
                for enb in tl_enb:
                    enb_module = enb.dus[0].airscale if hasattr(enb, "dus") else enb.system_module
                    for common_unit in enb_module.common_units:
                        if common_unit.hardware_type == self.smod_type:
                            for capacity_unit in common_unit.capacity_units:
                                if getattr(capacity_unit, "fhs"):
                                    self.reboot_fhs(capacity_unit.fhs[0].pdu_port.pdu.addr,
                                                    capacity_unit.fhs[0].pdu_port.port_no,
                                                    capacity_unit.fhs[0].pdu_port.pdu.model)

    @staticmethod
    def reboot_fhs(address: str, port: str, model: str, alias="fhs") -> None:
        test_logger("Rebooting FHS")
        try:
            pdu.setup_pdu(host=address, model=model, alias=alias)
            pdu.power_off(port=port, pdu_device=alias)
            time.sleep(2)
            pdu.power_on(port=port, pdu_device=alias)
        finally:
            pdu.teardown_pdu(pdu_device=alias)

    @method_decorator("node_alias")
    def update_software_on_affected_modules(self) -> None:
        if self.verify_if_fault_exists("23"):
            test_logger("Starting SW update to clear fid:23")
            self.admin.update_software(should_activate=True, sw_package=self.target_sw_path, timeout=2400)
            time.sleep(10)
            if self.verify_if_fault_exists(["23", "10"]):
                raise SoftwareStatusError("Software Update is not yet finished")
            test_logger("SW update finished")
        self.verify_node_bts_state()

    @method_decorator("node_alias")
    def run_yaft(self, build, yaft_path: str, command: str = None, virtualenv_dir: str = None):
        if self.local_host:
            virtualenv_dir_cmd = ""
        else:
            env_dir = self._get_virtualenv_dir(virtualenv_dir)
            virtualenv_dir_cmd = f"source {env_dir}/bin/activate; "
        switch = "-L -z" if self.smod_type in ("FSMF", "FSIH") else "-z"
        yaft_command = f'echo "{self.node_ssh_password}" | {yaft_path}/yaft.py -i ' \
                       f'{self.bts_host_ip} {switch} {yaft_path}/{build}*.zip --ask_for_password ' \
                       f'--clean_to_default --ignore_FSPs --fpga_update -v -K' if not command else command
        yaft_command = f"{virtualenv_dir_cmd}{yaft_command}"
        test_logger(f"Executing {yaft_command}", "DEBUG")
        output = self._ssh.execute(yaft_command, connection=self._ssh_vm_connection) if virtualenv_dir_cmd \
            else run_process(yaft_command)
        test_logger(output, console=False)

    def _get_virtualenv_dir(self, virtualenv_dir: str = None):
        if virtualenv_dir:
            return virtualenv_dir
        else:
            if self.local_host and "VIRTUAL_ENV" in os.environ:
                # we are on localhost and want to use current virtualenv
                virtualenv_dir = os.environ["VIRTUAL_ENV"]
            else:
                virtualenv_dir = "/home/ute/test_repo"
            return virtualenv_dir

    @staticmethod
    def _get_cm_tags() -> Union[list, str]:
        cm_tags = os.getenv("CM_TAGS")
        if cm_tags is None:
            return []
        return cm_tags

    @method_decorator("node_alias")
    def prepare_node_before_yaft(self, yaft_path: str, virtualenv_dir: str = None):
        if self.check_if_node_need_to_be_prepared_before_yaft():
            if self.get_active_sw().split("_")[0] not in ["SBTS21A", "SBTS21B"]:
                test_logger(f"Preparing node before yaft to {self.source_sw}")
                build = "SBTS21B_ENB_0000_002137_000000"
                run_process(f"scp {self.download_path}/{build}/*.zip "
                            f"{self.vm.get('host')}:{yaft_path}/{build}.zip")
                test_logger(f"Performing yaft to {build}")
                self.run_yaft(build, yaft_path, virtualenv_dir=virtualenv_dir)
            self.perform_uboot_downgrade()

    @method_decorator("node_alias")
    def perform_uboot_downgrade(self):
        try:
            self.uboot.uboot_downgrade()
        except Exception as e:
            test_logger(e, "error")

    @method_decorator("node_alias")
    def check_if_node_need_to_be_prepared_before_yaft(self):
        return self.smod_type == 'FSMF' and "LN_WN_FDSW19" in self.source_sw

    @method_decorator('node_alias')
    def get_technical_logs(self, logs_dir: str, filename: str = "snapshot"):
        test_logger("Gathering technical logs from Rescue Console")
        if not Path(logs_dir).exists():
            Path(logs_dir).mkdir(parents=True)
        try:
            self.fdsw_connection.download_technical_logs(path=logs_dir, log_filename=filename, timeout=300)
        except Exception as e:
            test_logger("Gathering technical logs from Rescue Console failed", log_level='Error')
            test_logger(e, console=False)

    @method_decorator("node_alias")
    def verify_if_fault_exists_rc(self, faults: Union[str, list]) -> bool:
        if not isinstance(faults, list):
            faults = [faults]
        fault_exists = True in [str(fault_id) == str(alarm.get("fault_id")) for fault_id in faults
                                for alarm in self.fdsw_connection.get_alarms(timeout=120)]
        return fault_exists

    @method_decorator('node_alias')
    def verify_fallback_fault(self):
        if not self.verify_if_fault_exists_rc(["4082", "4083", "4085", "4489"]):
            raise FallbackFaultNotAppear()

    @method_decorator('node_alias')
    def wait_on_active_fdsw(self, sw: str):
        wait_until_success(600, 10, self.verify_active_sw_version_via_ssh, sw)
        wait_until_success(300, 10, self.fdsw_connection.get_running_sw_version_name)

    @method_decorator('node_alias')
    def restore_target_sw(self):
        self.update_sw_operation_rc()
        self.operations_after_update_from_fdsw()
        self.verify_node_bts_state()

    @method_decorator('node_alias')
    def perform_activation_from_fdsw(self, fdsw_log_level):
        try:
            slot_id = "2" if self.fdsw_connection.get_active_sw_partition() == "1" else "1"
            self.fdsw_connection.software_rollback(sw_slot_id=slot_id, timeout=60)
        except Exception as e:
            test_logger(e, "error")
            self.setup_fdsw_connection(log_level=fdsw_log_level)
            slot_id = "2" if self.fdsw_connection.get_active_sw_partition() == "1" else "1"
            self.fdsw_connection.software_rollback(sw_slot_id=slot_id, timeout=60)

    @method_decorator('node_alias')
    def perform_activation_sbts_from_fdsw(self, fdsw_log_level):
        wait_until_success(600, 30, self.perform_activation_from_fdsw, fdsw_log_level)

    @method_decorator("node_alias")
    def turn_off_netboot_on_fdsw(self):
        def turn_off_netboot(slave_smod: bool) -> bool:
            if self.ssh_manager.get_module_type() in self.modules_with_netboot_off:
                return self.change_netboot_state("off", slave_smod)
            return False

        self.master_netboot_changed = turn_off_netboot(False)
        if self.ssh_manager.is_slave_smod():
            self.slave_netboot_changed = turn_off_netboot(True)
